def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    removed = set(int(c) for c in g[0] if c != bg)
    scene = g.copy()
    scene[0, :] = bg

    def runs(values):
        out = []
        for v in sorted(values):
            if not out or v != out[-1][-1] + 1:
                out.append([])
            out[-1].append(v)
        return out

    # decompose scaffold into rigid pieces: vertical poles (+ their bottom foot bar) and free bars
    pieces = []
    for obj in objects(scene, bg=bg):
        cells = set(obj['cells'])
        poles = []
        for x in sorted(set(x for y, x in cells)):
            for ys in runs([y for y, xx in cells if xx == x]):
                if len(ys) >= 2:
                    poles.append(dict(c=obj['colour'], v=set((y, x) for y in ys), h=set(), bar=False))
        used = set()
        for p in poles:
            used |= p['v']
        rest = cells - used
        for y in sorted(set(y for y, x in rest)):
            for xs in runs([x for yy, x in rest if yy == y]):
                bar = set((y, x) for x in xs)
                fits = [p for p in poles if max(yy for yy, xx in p['v']) == y
                        and ((y, xs[0] - 1) in p['v'] or (y, xs[-1] + 1) in p['v'])]
                if fits:
                    fits[0]['h'] |= bar
                else:
                    pieces.append(dict(c=obj['colour'], v=set(), h=bar, bar=not poles))
        pieces.extend(poles)

    # cleanup: a pole tip resting on a free bar of another colour extends one cell
    for p in pieces:
        if p['v']:
            y, x = max(p['v'])
            if any((y + 1, x) in q['h'] and q['c'] != p['c'] and q['bar'] for q in pieces):
                p['v'].add((y + 1, x))

    pieces = [p for p in pieces if p['c'] not in removed]

    def render():
        out = np.full_like(g, bg)
        for field in ['v', 'h']:
            for p in pieces:
                for y, x in p[field]:
                    out[y, x] = p['c']
        out[0] = g[0]
        return out

    if not any(int(v) in removed for row in scene for v in row):
        emit(g, 'No indicated colour occurs in the structure; preserve the grid.')
        return g

    emit(render(), 'Remove the indicated colours, keeping each pole and its bottom foot rigidly joined.')

    for step in range(H * len(pieces) + 1):
        stable = set()
        while True:
            occupied = set()
            for i in stable:
                occupied |= pieces[i]['v'] | pieces[i]['h']
            added = set()
            for i, p in enumerate(pieces):
                if i in stable:
                    continue
                cells = p['v'] | p['h']
                supported = any(y == H - 1 or (y + 1, x) in occupied or (y, x) in occupied for y, x in cells)
                for y in set(y for y, x in cells):
                    for xs in runs([x for yy, x in cells if yy == y]):
                        if (y, xs[0] - 1) in occupied and (y, xs[-1] + 1) in occupied:
                            supported = True
                if supported:
                    added.add(i)
            if not added:
                break
            stable |= added
        if len(stable) == len(pieces):
            out = render()
            emit(out, 'Every remaining rigid piece is supported; final settled structure.')
            return out
        for i, p in enumerate(pieces):
            if i not in stable:
                p['v'] = set((y + 1, x) for y, x in p['v'])
                p['h'] = set((y + 1, x) for y, x in p['h'])
        emit(render(), f'Gravity step {step + 1}: lower all unsupported rigid pieces by one row.')
    raise ValueError('Gravity did not settle within the finite grid bound')
